func (u *CanaryReleaseUpsertBulk) Update(set func(*CanaryReleaseUpsert)) *CanaryReleaseUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&CanaryReleaseUpsert{UpdateSet: update})
	}))
	return u
}

